# OpenAI streaming helper with simple retry on rate limits.
import time
from openai import OpenAI, RateLimitError

client = OpenAI()

def stream_answer(prompt, retries=3):
    for attempt in range(retries):
        try:
            # Stream tokens as they arrive instead of waiting for the full reply.
            stream = client.responses.create(model='gpt-4.1-mini', input=prompt, stream=True)
            for event in stream:
                if event.type == 'response.output_text.delta':
                    print(event.delta, end='')
            return
        except RateLimitError:
            time.sleep(2 ** attempt)  # back off before retrying

