# Gradebook helper for Mrs. Patel's seventh-grade science class.
# The feedback generator at the bottom is experimental; it was copied from an openai tutorial.
import statistics

GRADE_WEIGHTS = {'quizzes': 0.2, 'labs': 0.4, 'final': 0.4}

students = {
    'Amara': {'quizzes': [88, 92, 79], 'labs': [95, 90], 'final': 84},
    'Jonah': {'quizzes': [70, 65, 81], 'labs': [72, 78], 'final': 69},
    'Lena': {'quizzes': [97, 94, 99], 'labs': [91, 96], 'final': 93},
}

def weighted_grade(scores):
    # Average each category first so long quiz lists don't dominate.
    quiz_avg = statistics.mean(scores['quizzes'])
    lab_avg = statistics.mean(scores['labs'])
    final = scores['final']
    total = (quiz_avg * GRADE_WEIGHTS['quizzes']
             + lab_avg * GRADE_WEIGHTS['labs']
             + final * GRADE_WEIGHTS['final'])
    return round(total, 1)

def letter(score):
    # Simple cutoffs; adjust if the district changes its policy.
    if score >= 90:
        return 'A'
    if score >= 80:
        return 'B'
    if score >= 70:
        return 'C'
    return 'D'

for name, scores in students.items():
    g = weighted_grade(scores)
    print(f'{name}: {g} ({letter(g)})')

# TODO: send each student a short comment; the draft_feedback() function below will eventually call openai
# but needs an API key from the school account before it can run.
def draft_feedback(name, grade):
    return f'{name} earned {grade}. Keep practicing lab write-ups.'

