import numpy as np
from openai import OpenAI

client = OpenAI()

def embed(text):
    # Turn a string into a vector using OpenAI's embeddings endpoint
    result = client.embeddings.create(model='text-embedding-3-small', input=text)
    return np.array(result.data[0].embedding)

def cosine(a, b):
    # 1.0 means identical direction, 0 means unrelated
    return float(np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b)))

print(cosine(embed('cat'), embed('kitten')))

