import json
from openai import OpenAI

client = OpenAI()

# Describe a local Python function so the model knows it can ask for it
tools = [{
    'type': 'function',
    'function': {
        'name': 'get_temperature',
        'description': 'Return the current temperature in Celsius for a city',
        'parameters': {
            'type': 'object',
            'properties': {'city': {'type': 'string'}},
            'required': ['city'],
        },
    },
}]

def get_temperature(city):
    # Stub: a real version would call a weather service
    return {'city': city, 'celsius': 18}

messages = [{'role': 'user', 'content': 'How warm is it in Oslo?'}]
response = client.chat.completions.create(
    model='gpt-4o-mini', messages=messages, tools=tools
)

# With openai's tool calling, the model replies with the function name
# and JSON arguments instead of a final answer
call = response.choices[0].message.tool_calls[0]
args = json.loads(call.function.arguments)
print(get_temperature(**args))

# To finish the loop, append the tool result to messages with the
# role 'tool' and call the API a second time.

